// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }

    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0));
        amount = bound(amount, 1, 1 ether);

        vm.deal(actor, amount);
        vm.prank(actor);
        c.addToBalance{value: amount}();

        // second deposit from the same actor: only possible if the lock was released
        vm.deal(actor, amount);
        vm.prank(actor);
        bool ok;
        try c.addToBalance{value: amount}() {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok && c.getBalance(actor) == 2 * amount);
    }
}
